class Solution:
    def maxScore(self, n, k, x, arr):
        med_sums = []

        for length in range(1, n + 1):
            total = 0
            for i in range(n - length + 1):
                sub = arr[i:i+length]
                sub.sort()
                m = sub[length // 2]
                total += m
            med_sums.append(total)

        candidates = med_sums[:]
        result = 0

        for bit in range(31, -1, -1):
            temp = []
            for val in candidates:
                if (val >> bit) & 1:
                    temp.append(val)

            if len(temp) >= k:
                result |= (1 << bit)
                candidates = temp

        return x | result
